(() => {
  const photos = {
    biankatemperine: "data:image/jpeg;base64,",
    hmproducoes: "data:image/jpeg;base64,"
  };
  photos.assessorabiankatemperine = photos.biankatemperine;
  const normalize = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'').toLowerCase();
  const apply = () => document.querySelectorAll('.supplier-card').forEach(card => {
    const source = photos[normalize(card.querySelector('h3')?.textContent)];
    const logo = card.querySelector('.supplier-logo');
    if (!source || !logo) return;
    logo.classList.add('has-photo','has-supplier-logo');
    let image = logo.querySelector('.supplier-photo');
    if (!image) { image = document.createElement('img'); image.className='supplier-photo'; logo.prepend(image); }
    image.src = source;
    image.alt = card.querySelector('h3')?.textContent?.trim() || 'Logo do fornecedor';
  });
  window.addEventListener('load', () => { apply(); setTimeout(apply,3000); });
  const grid=document.querySelector('#supplierGrid');
  if(grid)new MutationObserver(apply).observe(grid,{childList:true,subtree:true});
})();
